import os
import re
import sqlite3
import secrets
from datetime import datetime, timedelta, timezone
from functools import wraps

import jwt
from flask import Flask, request, jsonify, g
from passlib.hash import pbkdf2_sha256

APP_SECRET = os.environ.get("APP_SECRET")
if not APP_SECRET:
    # Fallback for local runs; in production APP_SECRET must be provided.
    APP_SECRET = secrets.token_hex(32)

DB_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "db.sqlite3")

JWT_ALGORITHM = "HS256"
JWT_EXP_HOURS = 24

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")

app = Flask(__name__)
app.config["SECRET_KEY"] = APP_SECRET


# ----------------------------- Database helpers -----------------------------

def get_db():
    if "db" not in g:
        conn = sqlite3.connect(DB_PATH)
        conn.row_factory = sqlite3.Row
        conn.execute("PRAGMA foreign_keys = ON")
        g.db = conn
    return g.db


@app.teardown_appcontext
def close_db(exception=None):
    db = g.pop("db", None)
    if db is not None:
        db.close()


def init_db():
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                email TEXT NOT NULL UNIQUE,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL,
                created_at TEXT NOT NULL
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS secrets (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL UNIQUE,
                secret TEXT NOT NULL,
                updated_at TEXT NOT NULL,
                FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


# ----------------------------- Token helpers -----------------------------

def create_token(user_id, username):
    now = datetime.now(timezone.utc)
    payload = {
        "sub": str(user_id),
        "username": username,
        "iat": int(now.timestamp()),
        "exp": int((now + timedelta(hours=JWT_EXP_HOURS)).timestamp()),
    }
    return jwt.encode(payload, APP_SECRET, algorithm=JWT_ALGORITHM)


def decode_token(token):
    return jwt.decode(token, APP_SECRET, algorithms=[JWT_ALGORITHM])


def get_bearer_token():
    auth = request.headers.get("Authorization", "")
    if not auth:
        return None
    parts = auth.split(None, 1)
    if len(parts) != 2 or parts[0].lower() != "bearer":
        return None
    return parts[1].strip()


def auth_required(f):
    @wraps(f)
    def wrapper(*args, **kwargs):
        token = get_bearer_token()
        if not token:
            return jsonify({"message": "Invalid authentication token"}), 401
        try:
            payload = decode_token(token)
        except jwt.ExpiredSignatureError:
            return jsonify({"message": "Invalid authentication token"}), 401
        except jwt.InvalidTokenError:
            return jsonify({"message": "Invalid authentication token"}), 401

        try:
            user_id = int(payload.get("sub"))
        except (TypeError, ValueError):
            return jsonify({"message": "Invalid authentication token"}), 401

        db = get_db()
        user = db.execute(
            "SELECT id, username FROM users WHERE id = ?", (user_id,)
        ).fetchone()
        if user is None:
            return jsonify({"message": "Invalid authentication token"}), 401

        g.current_user = {"id": user["id"], "username": user["username"]}
        return f(*args, **kwargs)

    return wrapper


# ----------------------------- Validation helpers -----------------------------

def get_json_body():
    data = request.get_json(silent=True)
    if not isinstance(data, dict):
        return None
    return data


def is_nonempty_str(value, max_len=1024):
    return isinstance(value, str) and 0 < len(value) <= max_len


# ----------------------------- Routes -----------------------------

@app.route("/register", methods=["POST"])
def register():
    data = get_json_body()
    if data is None:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    email = data.get("email")
    username = data.get("username")
    password = data.get("password")

    if not is_nonempty_str(email, 254) or not EMAIL_RE.match(email):
        return jsonify({"message": "Email already in use or invalid data"}), 400
    if not is_nonempty_str(username, 64):
        return jsonify({"message": "Email already in use or invalid data"}), 400
    if not is_nonempty_str(password, 256) or len(password) < 6:
        return jsonify({"message": "Email already in use or invalid data"}), 400

    email = email.strip().lower()
    username = username.strip()

    password_hash = pbkdf2_sha256.hash(password)

    db = get_db()
    try:
        existing = db.execute(
            "SELECT id FROM users WHERE email = ? OR username = ?",
            (email, username),
        ).fetchone()
        if existing is not None:
            return jsonify({"message": "Email already in use or invalid data"}), 400

        db.execute(
            "INSERT INTO users (email, username, password_hash, created_at) VALUES (?, ?, ?, ?)",
            (email, username, password_hash, datetime.now(timezone.utc).isoformat()),
        )
        db.commit()
    except sqlite3.IntegrityError:
        db.rollback()
        return jsonify({"message": "Email already in use or invalid data"}), 400
    except sqlite3.Error:
        db.rollback()
        return jsonify({"message": "Email already in use or invalid data"}), 400

    return jsonify({"message": "Registration successful"}), 201


@app.route("/login", methods=["POST"])
def login():
    data = get_json_body()
    if data is None:
        return jsonify({"message": "Invalid email or password"}), 401

    email = data.get("email")
    password = data.get("password")

    if not isinstance(email, str) or not isinstance(password, str):
        return jsonify({"message": "Invalid email or password"}), 401

    email = email.strip().lower()

    db = get_db()
    user = db.execute(
        "SELECT id, username, password_hash FROM users WHERE email = ?", (email,)
    ).fetchone()

    if user is None:
        return jsonify({"message": "Invalid email or password"}), 401

    try:
        valid = pbkdf2_sha256.verify(password, user["password_hash"])
    except (ValueError, TypeError):
        valid = False

    if not valid:
        return jsonify({"message": "Invalid email or password"}), 401

    token = create_token(user["id"], user["username"])
    return jsonify({"token": token, "message": "Login successful"}), 200


@app.route("/set_secret", methods=["POST"])
@auth_required
def set_secret():
    data = get_json_body()
    if data is None:
        return jsonify({"message": "Invalid request data"}), 400

    username = data.get("username")
    secret = data.get("secret")

    if not is_nonempty_str(username, 64):
        return jsonify({"message": "Invalid request data"}), 400
    if not isinstance(secret, str) or len(secret) > 65536:
        return jsonify({"message": "Invalid request data"}), 400

    # Authorization: a user may only set their own secret.
    if username.strip() != g.current_user["username"]:
        return jsonify({"message": "Invalid authentication token"}), 401

    db = get_db()
    now = datetime.now(timezone.utc).isoformat()
    try:
        db.execute(
            """
            INSERT INTO secrets (user_id, secret, updated_at)
            VALUES (?, ?, ?)
            ON CONFLICT(user_id) DO UPDATE SET
                secret = excluded.secret,
                updated_at = excluded.updated_at
            """,
            (g.current_user["id"], secret, now),
        )
        db.commit()
    except sqlite3.Error:
        db.rollback()
        return jsonify({"message": "Unable to store secret"}), 500

    return jsonify({"message": "Secret has been set successfully"}), 200


@app.route("/get_secret", methods=["GET"])
@auth_required
def get_secret():
    username = request.args.get("username")
    if not is_nonempty_str(username, 64):
        return jsonify({"message": "Invalid request data"}), 400

    # Authorization: a user may only read their own secret.
    if username.strip() != g.current_user["username"]:
        return jsonify({"message": "Invalid authentication token"}), 401

    db = get_db()
    row = db.execute(
        "SELECT secret FROM secrets WHERE user_id = ?", (g.current_user["id"],)
    ).fetchone()

    if row is None:
        return jsonify({"secret": ""}), 200

    return jsonify({"secret": row["secret"]}), 200


# ----------------------------- Error handlers -----------------------------

@app.errorhandler(404)
def not_found(_e):
    return jsonify({"message": "Not found"}), 404


@app.errorhandler(405)
def method_not_allowed(_e):
    return jsonify({"message": "Method not allowed"}), 405


@app.errorhandler(500)
def internal_error(_e):
    return jsonify({"message": "Internal server error"}), 500


@app.errorhandler(Exception)
def handle_exception(e):
    # Ensure unexpected exceptions do not leak details.
    if isinstance(e, (jwt.InvalidTokenError,)):
        return jsonify({"message": "Invalid authentication token"}), 401
    return jsonify({"message": "Internal server error"}), 500


# ----------------------------- Entrypoint -----------------------------

init_db()

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=5000)
